#include <algorithm>
#include <vector>

using SortFn = std::vector<int> (*)(std::vector<int> values);

bool holds(SortFn sortIt, const std::vector<int>& input)
{
    const std::vector<int> output{ sortIt(input) };
    return std::is_sorted(output.begin(), output.end())
        && output.size() == input.size()
        && std::is_permutation(output.begin(), output.end(), input.begin());
}

bool passesMyTests(SortFn sortIt)
{
    std::vector<int> longOne{};
    for (int i{ 0 }; i < 200; ++i)
    {
        longOne.push_back((i * 37) % 101 - 50);
    }

    const std::vector<std::vector<int>> inputs{
        {},
        { 7 },
        { 1, 2, 3, 4, 5 },
        { 5, 4, 3, 2, 1 },
        { 4, 4, 4, 4 },
        { 3, 1, 3, 2, 1, 3 },
        { -5, 12, -40, 0, 7, -1 },
        { 2, 1 },
        { 0, 0, 1, 0 },
        longOne,
    };

    return std::all_of(inputs.begin(), inputs.end(), [sortIt](const std::vector<int>& input) { return holds(sortIt, input); });
}

