namespace mutants {
    using V = std::vector<int>;
    V correct(V v) { std::sort(v.begin(), v.end()); return v; }
    V doesNothing(V v) { return v; }
    V descending(V v) { std::sort(v.begin(), v.end(), std::greater<>{}); return v; }
    V dropsDuplicates(V v) { std::sort(v.begin(), v.end()); v.erase(std::unique(v.begin(), v.end()), v.end()); return v; }
    V losesTheLast(V v) { if (v.size() > 3) v.pop_back(); std::sort(v.begin(), v.end()); return v; }
    V skipsTheFirst(V v) { if (v.size() > 1) std::sort(v.begin() + 1, v.end()); return v; }
    V sortsByMagnitude(V v) { std::sort(v.begin(), v.end(), [](int a, int b) { return (a < 0 ? -a : a) < (b < 0 ? -b : b); }); return v; }
    V inventsValues(V v) { std::sort(v.begin(), v.end()); for (std::size_t i{ 1 }; i < v.size(); ++i) if (v[i] == v[i - 1]) v[i] = v[i - 1] + 1; std::sort(v.begin(), v.end()); return v; }
    V onlyShortInputs(V v) { if (v.size() <= 16) std::sort(v.begin(), v.end()); return v; }
    V addsToEmpty(V v) { if (v.empty()) v.push_back(0); std::sort(v.begin(), v.end()); return v; }
    V fillsWithSmallest(V v) { if (!v.empty()) { const int m{ *std::min_element(v.begin(), v.end()) }; std::fill(v.begin(), v.end(), m); } return v; }
}

TEST("a correct sort passes your tests") { CHECK(passesMyTests(mutants::correct)); }
TEST("caught: does not sort at all") { CHECK(!passesMyTests(mutants::doesNothing)); }
TEST("caught: sorts in the wrong direction") { CHECK(!passesMyTests(mutants::descending)); }
TEST("caught: drops duplicates") { CHECK(!passesMyTests(mutants::dropsDuplicates)); }
TEST("caught: loses an element") { CHECK(!passesMyTests(mutants::losesTheLast)); }
TEST("caught: leaves the first element where it was") { CHECK(!passesMyTests(mutants::skipsTheFirst)); }
TEST("caught: mishandles negative numbers") { CHECK(!passesMyTests(mutants::sortsByMagnitude)); }
TEST("caught: changes repeated values") { CHECK(!passesMyTests(mutants::inventsValues)); }
TEST("caught: gives up on long inputs") { CHECK(!passesMyTests(mutants::onlyShortInputs)); }
TEST("caught: adds an element to an empty input") { CHECK(!passesMyTests(mutants::addsToEmpty)); }
TEST("caught: sorted, but not the same values") { CHECK(!passesMyTests(mutants::fillsWithSmallest)); }

